import { useCallback, useMemo, useState } from "react";
import Auth from "./components/Auth";
import Board from "./components/Board";
import CanvasDashboard from "./components/CanvasDashboard";
import Toolbar from "./components/Toolbar";
import Toolbox from "./components/Toolbox";
import BoardProvider from "./store/BoardProvider";
import ToolBoxProvider from "./store/toolboxProvider";
import { saveCanvas } from "./api/canvas";
import { hydrateElements, serializeElements } from "./utils/element";
import classes from "./App.module.css";

const readSession = () => {
  try {
    const session = JSON.parse(localStorage.getItem("whiteboard-session"));
    return session?.token ? session : null;
  } catch (error) {
    localStorage.removeItem("whiteboard-session");
    return null;
  }
};

const ActiveCanvas = ({ token, canvas, onBack, onSignOut }) => {
  const [saveStatus, setSaveStatus] = useState("All changes saved");
  const initialElements = useMemo(
    () => hydrateElements(canvas.elements || []),
    [canvas._id, canvas.elements]
  );
  const saveElements = useCallback(async (elements) => {
    setSaveStatus("Saving…");
    try {
      await saveCanvas(token, canvas._id, serializeElements(elements));
      setSaveStatus("All changes saved");
    } catch (error) {
      if (error.status === 401) {
        onSignOut();
        return;
      }
      setSaveStatus(`Save failed: ${error.message}`);
    }
  }, [token, canvas._id, onSignOut]);

  return (
    <BoardProvider
      key={canvas._id}
      initialElements={initialElements}
      onElementsChange={saveElements}
    >
      <ToolBoxProvider>
        <div className={classes.canvasHeader}>
          <button type="button" onClick={onBack}>← Canvases</button>
          <span>Whiteboard · {canvas._id}</span>
          <span className={classes.saveStatus} role="status">{saveStatus}</span>
          <button type="button" onClick={onSignOut}>Sign out</button>
        </div>
        <Toolbar />
        <Board />
        <Toolbox />
      </ToolBoxProvider>
    </BoardProvider>
  );
};

function App() {
  const [session, setSession] = useState(readSession);
  const [activeCanvas, setActiveCanvas] = useState(null);

  const signOut = useCallback(() => {
    localStorage.removeItem("whiteboard-session");
    setSession(null);
    setActiveCanvas(null);
  }, []);

  const acceptSession = (result) => {
    const nextSession = { token: result.token, user: result.user };
    localStorage.setItem("whiteboard-session", JSON.stringify(nextSession));
    setSession(nextSession);
  };

  if (!session) return <Auth onAuthenticated={acceptSession} />;
  if (activeCanvas) {
    return (
      <ActiveCanvas
        token={session.token}
        canvas={activeCanvas}
        onBack={() => setActiveCanvas(null)}
        onSignOut={signOut}
      />
    );
  }
  return (
    <CanvasDashboard
      token={session.token}
      user={session.user}
      onOpenCanvas={setActiveCanvas}
      onSignOut={signOut}
      onUnauthorized={signOut}
    />
  );
}

export default App;
